// Parse the LLM response and build avatar URL
const body = $('Webhook').item.json.body;
const llmResponse = $input.item.json;
const content = llmResponse.choices?.[0]?.message?.content || '{}';

let profile;
try {
    // Clean markdown code fences if present
    const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    profile = JSON.parse(cleaned);
} catch (e) {
    profile = {
        name: 'Elif ' + Date.now().toString(36).slice(-4),
        personality: 'Karizmatik, enerjik ve samimi. Gerçek tutkusuyla izleyicileriyle bağ kurar.',
        backstory: 'İstanbul doğumlu, dijital pazarlama dünyasında kendini bulan tutkulu bir içerik üreticisi.',
        appearanceDescription: 'Turkish woman with warm olive skin, dark brown hair, expressive brown eyes, professional appearance',
        visualProfile: { gender: body.gender || 'female', ageRange: '25-35', style: 'business casual', features: 'expressive dark eyes, olive skin' }
    };
}

const vp = profile.visualProfile || {};
const gender = (body.gender || vp.gender || 'female') === 'male' ? 'man' : 'woman';
const age = vp.ageRange || '28';
const seed = Math.floor(Math.random() * 999999);

const hairStyles = ['dark brown-haired', 'black-haired', 'chestnut brown-haired', 'dark auburn-haired', 'deep brown-haired'];
const backgrounds = ['soft blue', 'warm beige', 'light gray', 'pastel green', 'gradient purple', 'teal'];
const expressions = ['warm smile', 'confident gaze', 'friendly expression', 'bright smile'];

const hair = hairStyles[Math.floor(Math.random() * hairStyles.length)];
const bg = backgrounds[Math.floor(Math.random() * backgrounds.length)];
const expr = expressions[Math.floor(Math.random() * expressions.length)];

const appearance = (profile.appearanceDescription || '').replace(/[^a-zA-Z0-9 ,.\-]/g, '').substring(0, 100);
const promptText = `photorealistic portrait headshot of a Turkish ${hair} ${gender} aged ${age}, Mediterranean olive skin tone, ${appearance || vp.style || 'professional'}, ${bg} background, studio lighting, ${expr}, 8k uhd`;
const encodedPrompt = encodeURIComponent(promptText);
const avatarUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=512&height=512&seed=${seed}&nologo=true&model=flux`;

return [{
    json: {
        projectId: body.projectId,
        gender: body.gender || 'female',
        name: profile.name,
        personality: profile.personality,
        backstory: profile.backstory,
        appearanceDescription: profile.appearanceDescription,
        visualProfile: profile.visualProfile,
        avatarUrl: avatarUrl
    }
}];
